children.push(punto("Mensajes: estructuras tipadas definidas en ficheros .msg; ejemplos que verán en el taller: sensor_msgs/msg/LaserScan, geometry_msgs/msg/Twist, nav_msgs/msg/Odometry."));
children.push(punto("Demo en vivo (5 min, con el portátil del aula): ros2 run demo_nodes_cpp talker en una terminal y ros2 run demo_nodes_py listener en otra; enseñar que son procesos independientes y hasta de lenguajes distintos."));
